12	{"id": "first-save-beside-source", "name": "The first Save goes beside the source", "summary": "The first Save of a project made from a file offers to put the package next to the source file, under the source's name.", "page": "projects/start-a-project", "anchor": "save-it-for-the-first-time", "where": "File ▸ Save (⌘S)", "keys": "⌘S"}
