14	{"id": "welcome-open-video", "name": "Open Video…", "summary": "The Welcome window's default button is the same open panel as File ▸ Open….", "page": "projects/welcome-window", "anchor": "start-something", "where": "Welcome window ▸ Open Video…"}
15	{"id": "welcome-new-project", "name": "New Project on the Welcome window", "summary": "Starts a blank 1920 × 1080, 30 fps project.", "page": "projects/welcome-window", "anchor": "start-something", "where": "Welcome window ▸ New Project"}
16	{"id": "welcome-new-recording", "name": "New Recording… on the Welcome window", "summary": "Opens the recorder panel with no project open.", "page": "projects/welcome-window", "anchor": "start-something", "where": "Welcome window ▸ New Recording…"}
