18	{"id": "welcome-file-types-line", "name": "The file types line", "summary": "The foot of the window lists what it opens: MOV · MP4 · M4V · M4A · MP3 · WAV · AIFF · PNG · JPEG · HEIC.", "page": "projects/welcome-window", "anchor": "drop-files-on-it", "where": "Welcome window, foot"}
19	{"id": "welcome-drop-files", "name": "Drop files on the Welcome window", "summary": "A file or package dropped anywhere on the Welcome window opens, each as its own document.", "page": "projects/welcome-window", "anchor": "drop-files-on-it", "where": "Drag files from the Finder onto the Welcome window"}
