21	{"id": "open-recent", "name": "Open Recent", "summary": "File ▸ Open Recent lists recently opened projects, with Clear Menu to empty the list.", "page": "projects/open-a-project", "anchor": "open-a-recent-project", "where": "File ▸ Open Recent ▸"}
22	{"id": "open-already-open", "name": "A project already open comes forward", "summary": "Opening a project that is already open brings its window forward instead of opening it twice.", "page": "projects/open-a-project", "anchor": "open-a-project-thats-already-open"}
23	{"id": "open-by-drop", "name": "Drop files to open them", "summary": "Files dropped on a project window outside the Media tab, on the Welcome window or on the Dock icon each open as a document of their own.", "page": "projects/open-a-project", "anchor": "drop-files-to-open-them", "where": "Drag from the Finder onto a project window, outside the Media tab"}
