25	{"id": "open-newer-project-refused", "name": "Newer projects are refused", "summary": "A package saved by a newer Frame Job reports its version and asks you to update.", "page": "projects/open-a-project", "anchor": "open-a-project-from-another-version", "where": "File ▸ Open… (⌘O)", "keys": "⌘O"}
26	{"id": "open-damaged-project", "name": "Damaged projects", "summary": "A damaged or out-of-range project fails to open with a message naming the problem, and the package is not rewritten.", "page": "projects/open-a-project", "anchor": "when-a-project-wont-open"}
27	{"id": "open-missing-media", "name": "Missing media still opens", "summary": "A project whose files have moved opens with slates in their place and offers to relink them.", "page": "projects/open-a-project", "anchor": "open-a-project-with-missing-files", "where": "File ▸ Open… (⌘O)", "keys": "⌘O"}
28	{"id": "new-project-from-range", "name": "New Project from Range", "summary": "Opens a new project holding exactly the timeline's In–Out range, moved to start at 0, and leaves the source project unchanged.", "page": "projects/new-project-from-range", "anchor": "make-a-project-from-a-range", "where": "File ▸ New Project from Range…"}
29	{"id": "range-cuts-clips-at-edges", "name": "Clips cut at the range's edges", "summary": "A clip across the range's In or Out is cut there as Split cuts it; markers inside are kept and media no kept clip plays is left out.", "page": "projects/new-project-from-range", "anchor": "what-is-kept"}
30	{"id": "range-naming-and-undo", "name": "The new project's name and undo", "summary": "The new project opens untitled with unsaved changes, named after its parent with \" (range)\" added, such as \"Interview (range)\".", "page": "projects/new-project-from-range", "anchor": "the-new-projects-name-and-undo"}
31	{"id": "range-brings-caches", "name": "Caches come along", "summary": "Each kept media's filmstrip, waveform, loudness, speech and sync caches, on-device transcripts, analyses and reversed-clip renders come along, so nothing is measured again.", "page": "projects/new-project-from-range", "anchor": "what-comes-with-it"}
32	{"id": "range-cloud-transcripts", "name": "Cloud transcripts in a range project", "summary": "A cloud transcript goes to the range project only once AssemblyAI has been told to delete its copy.", "page": "projects/new-project-from-range", "anchor": "cloud-transcripts", "needs": "your AssemblyAI key"}
33	{"id": "range-brings-graphics", "name": "Graphics come along", "summary": "The graphic modules the kept clips draw, and every font and picture of the project's graphics, come along.", "page": "projects/new-project-from-range", "anchor": "graphics"}
34	{"id": "range-refusals", "name": "When a range is refused", "summary": "If the range cannot be kept the item beeps and shows why at the foot of the inspector.", "page": "projects/new-project-from-range", "anchor": "when-frame-job-wont-do-it"}
35	{"id": "save-project", "name": "Save", "summary": "Writes the package; an untitled project asks where.", "page": "projects/save-and-revert", "anchor": "save-a-project", "where": "File ▸ Save (⌘S)", "keys": "⌘S"}
36	{"id": "save-as-and-duplicate", "name": "Save As and Duplicate", "summary": "Duplicate opens a copy of the project as a new untitled document; hold ⌥ and the item becomes Save As…, which writes the project to a new package.", "page": "projects/save-and-revert", "anchor": "make-a-copy", "where": "File ▸ Duplicate (⇧⌘S)", "keys": "⇧⌘S"}
