39	{"id": "revert-to", "name": "Revert To and browsing versions", "summary": "Goes back to the last saved version, or browses earlier versions of the package.", "page": "projects/save-and-revert", "anchor": "revert-to-an-earlier-version", "where": "File ▸ Revert To ▸"}
40	{"id": "rename-project", "name": "Rename", "summary": "The standard macOS command renames the project's package, from the File menu or the window's title.", "page": "projects/save-and-revert", "anchor": "rename-or-move-a-project", "where": "File ▸ Rename…"}
41	{"id": "move-project", "name": "Move To", "summary": "The standard macOS command moves the project's package to another folder, from the File menu or the window's title.", "page": "projects/save-and-revert", "anchor": "rename-or-move-a-project", "where": "File ▸ Move To…"}
