61	{"id": "add-media", "name": "Add Media", "summary": "Adds one or more files to the Media tab as one undo step, without putting them on the timeline.", "page": "projects/import-media", "anchor": "add-media", "where": "File ▸ Add Media… (⇧⌘I)", "keys": "⇧⌘I"}
62	{"id": "drop-on-media-tab", "name": "Drop files on the Media tab", "summary": "Dragging files from the Finder onto the Media tab adds them to this project.", "page": "projects/import-media", "anchor": "drop-on-the-media-tab", "where": "Drag from the Finder onto the Media tab"}
