70	{"id": "copying-movie-window", "name": "The Copying Movie window", "summary": "A copy that takes more than a second shows a small progress window with Cancel.", "page": "projects/webm-and-matroska", "anchor": "the-copying-movie-window", "where": "Copying Movie window ▸ Cancel"}
71	{"id": "rewrap-free-space-check", "name": "The free-space check", "summary": "Frame Job checks the disk has room before copying and refuses if it does not.", "page": "projects/webm-and-matroska", "anchor": "free-space"}
72	{"id": "rewrapped-folder", "name": "The Rewrapped folder", "summary": "Copies live in ~/Library/Application Support/Frame Job/Rewrapped/, shared by all projects, and Frame Job never deletes from it.", "page": "projects/webm-and-matroska", "anchor": "the-rewrapped-folder"}
73	{"id": "rewrapped-media-name", "name": "A copied file keeps its name", "summary": "The media keeps the original's name, and its Media tab tooltip says where the copy lives.", "page": "projects/webm-and-matroska", "anchor": "the-name-in-the-media-tab"}
74	{"id": "rewrap-unsupported-streams", "name": "Streams the copy cannot carry", "summary": "A stream the built-in copy cannot carry is refused with a sentence naming it, and with ffmpeg installed Frame Job then offers to help.", "page": "projects/webm-and-matroska", "anchor": "streams-the-copy-cant-carry", "where": "File ▸ Add Media… (⇧⌘I)", "keys": "⇧⌘I"}
75	{"id": "rewrap-keeps-colour", "name": "Stated colour is kept", "summary": "The copy keeps the colour the file states: HLG, HDR10 (PQ), or a BT.709, BT.601 or BT.2020 SDR picture.", "page": "projects/webm-and-matroska", "anchor": "colour-is-kept"}
76	{"id": "rewrap-copy-remade", "name": "A missing copy is remade", "summary": "If a copy is deleted or moved to the Trash, the project makes it again from the original on its next open.", "page": "projects/webm-and-matroska", "anchor": "if-a-copy-goes-missing", "where": "Project open"}
