78	{"id": "ffmpeg-search-path", "name": "Finding ffmpeg", "summary": "Frame Job looks for ffmpeg on PATH first, then in the usual install folders, and a defaults key can name a particular build.", "page": "projects/ffmpeg-conversion", "anchor": "finding-ffmpeg", "where": "Terminal: defaults write com.kgalligan.FrameJob RCFFmpegPath /path/to/ffmpeg", "needs": "ffmpeg"}
