80	{"id": "ffmpeg-remember-answer", "name": "Do this automatically from now on", "summary": "Ticking the box remembers the answer given: always if you accepted, never if you cancelled.", "page": "projects/ffmpeg-conversion", "anchor": "remember-your-answer", "where": "Alert ▸ Do this automatically from now on", "needs": "ffmpeg"}
81	{"id": "ffmpeg-failed-conversion", "name": "A failed conversion", "summary": "A conversion that fails shows \"Could not convert file with ffmpeg: reason\".", "page": "projects/ffmpeg-conversion", "anchor": "when-a-conversion-fails", "needs": "ffmpeg"}
