83	{"id": "ffmpeg-agent-imports", "name": "Agent imports and ffmpeg", "summary": "An agent's import never shows the ffmpeg question: unless you chose always, the offer counts as declined and the file is refused with the reason.", "page": "projects/ffmpeg-conversion", "anchor": "with-an-agent", "needs": "ffmpeg"}
84	{"id": "media-tab", "name": "The Media tab", "summary": "The inspector's Media tab lists every file the project has imported, used or not, in a bar, a find band, the list and a footer.", "page": "projects/media-tab", "anchor": "what-the-tab-shows", "where": "Inspector ▸ Media"}
85	{"id": "media-item-count", "name": "The item count", "summary": "The top bar holds Add Media… and a count of the files, and of how many are showing.", "page": "projects/media-tab", "anchor": "the-item-count", "where": "Inspector ▸ Media ▸ top bar"}
86	{"id": "media-search", "name": "Search by name", "summary": "A Search by name field filters the list as you type, ignoring case and accents, as Finder does.", "page": "projects/media-tab", "anchor": "search-by-name", "where": "Inspector ▸ Media ▸ Search by name", "keys": "Esc"}
87	{"id": "media-sort", "name": "Sort", "summary": "A Sort popup orders the list by Import Order, Name, Duration or Kind.", "page": "projects/media-tab", "anchor": "sort", "where": "Inspector ▸ Media ▸ Sort"}
88	{"id": "media-unused-only", "name": "Unused only", "summary": "A checkbox shows only the files no clip uses.", "page": "projects/media-tab", "anchor": "unused-only", "where": "Inspector ▸ Media ▸ Unused only"}
89	{"id": "media-row", "name": "A media row", "summary": "Each row shows a thumbnail, the file's name and an info line for its kind.", "page": "projects/media-tab", "anchor": "read-a-row", "where": "Inspector ▸ Media ▸ row"}
